type
  Box =
    object
      value:
        int


proc `+`(
    a,
    b:
      Box
): Box =
  Box(
    value:
      a.value +
      b.value
  )


proc `-`(
    a,
    b:
      Box
): Box =
  Box(
    value:
      a.value -
      b.value
  )


var tree =
  initSparseDualFenwickTree2D[
    int
  ](
    Height,
    Width,
  )


doAssert tree.height() ==
  Height

doAssert tree.width() ==
  Width


for index in 0 ..< LogicalQueryCount:
  let event =
    Events[
      index
    ]

  tree.add(
    event[0],
    event[1],
    event[2],
    event[3],
    event[4],
  )

  var actual:
    int

  if (
    index and 1
  ) == 0:
    actual =
      tree.get(
        event[5],
        event[6],
      )
  else:
    actual =
      tree[
        event[5],
        event[6]
      ]

  doAssert actual ==
    ExpectedValues[
      index
    ]


block genericAdditiveGroup:
  var boxTree =
    initSparseDualFenwickTree2D[
      Box
    ](
      20,
      30,
    )

  doAssert boxTree.height() ==
    20

  doAssert boxTree.width() ==
    30

  boxTree.add(
    3,
    15,
    7,
    25,
    Box(
      value:
        9
    ),
  )

  boxTree.add(
    10,
    20,
    20,
    30,
    Box(
      value:
        -4
    ),
  )

  doAssert boxTree.get(
    5,
    10,
  ).value ==
    9

  doAssert boxTree[
    12,
    22
  ].value ==
    5

  doAssert boxTree.get(
    19,
    29,
  ).value ==
    -4


block fullBoundaryRectangle:
  var full =
    initSparseDualFenwickTree2D[
      int
    ](
      11,
      13,
    )

  full.add(
    0,
    11,
    0,
    13,
    7,
  )

  doAssert full.get(
    0,
    0,
  ) ==
    7

  doAssert full.get(
    5,
    6,
  ) ==
    7

  doAssert full[
    10,
    12
  ] ==
    7


block emptyRectangles:
  var emptyRect =
    initSparseDualFenwickTree2D[
      int
    ](
      9,
      10,
    )

  emptyRect.add(
    4,
    4,
    2,
    9,
    100,
  )

  emptyRect.add(
    2,
    8,
    5,
    5,
    100,
  )

  doAssert emptyRect.get(
    4,
    6,
  ) ==
    0


block cancellation:
  var cancel =
    initSparseDualFenwickTree2D[
      int
    ](
      12,
      14,
    )

  cancel.add(
    2,
    10,
    3,
    12,
    17,
  )

  cancel.add(
    2,
    10,
    3,
    12,
    -17,
  )

  doAssert cancel.get(
    5,
    7,
  ) ==
    0


block emptyDimensions:
  var empty00 =
    initSparseDualFenwickTree2D[
      int
    ](
      0,
      0,
    )

  doAssert empty00.height() ==
    0

  doAssert empty00.width() ==
    0

  empty00.add(
    0,
    0,
    0,
    0,
    9,
  )

  var emptyHeight =
    initSparseDualFenwickTree2D[
      int
    ](
      0,
      17,
    )

  emptyHeight.add(
    0,
    0,
    0,
    17,
    9,
  )

  var emptyWidth =
    initSparseDualFenwickTree2D[
      int
    ](
      23,
      0,
    )

  emptyWidth.add(
    0,
    23,
    0,
    0,
    9,
  )


block machineWideDimensions:
  var wide =
    initSparseDualFenwickTree2D[
      int
    ](
      high(int),
      high(int),
    )

  doAssert wide.height() ==
    high(int)

  doAssert wide.width() ==
    high(int)

  wide.add(
    high(int) - 2,
    high(int),
    high(int) - 2,
    high(int),
    11,
  )

  doAssert wide.get(
    high(int) - 1,
    high(int) - 1,
  ) ==
    11

  wide.add(
    0,
    high(int),
    0,
    high(int),
    3,
  )

  doAssert wide.get(
    high(int) - 1,
    high(int) - 1,
  ) ==
    14

  doAssert wide[
    0,
    0
  ] ==
    3


echo(
  "SPARSE_DUAL_FENWICK_TREE_2D_CONTRACT_OK queries=" &
  $LogicalQueryCount &
  " oracle=" &
  OracleSha
)
